function preview(state){const value=state.preview;if(!state.previewOpen||!value)return '';const source=value.snapshot.source,base=value.snapshot.baseSnapshot;
  const body=state.previewView==='source'?`${base?`<details class="lt-summary-source" data-cu-open="base"><summary>上一版记忆</summary><p>${esc(base.body)}</p></details>`:''}${source.sentFloors.map(item=>`<details class="lt-summary-source" data-cu-open="floor:${item.floor}"><summary>第 ${item.floor} 楼 · ${item.role==='user'?'用户':'AI'}</summary><p>${esc(item.text)}</p></details>`).join('')}`:value.previewParts.map((part,index)=>`<details class="lt-summary-prompt" data-cu-open="prompt:${index}"><summary><span class="lt-summary-prompt-label"><span>${esc(part.name)}</span><small class="lt-meta">${esc(part.role.toUpperCase())}</small></span></summary><pre>${esc(part.content)}</pre></details>`).join('');
  return `<section class="lt-summary-preview ui-preview-panel"><nav class="lt-summary-switches ui-preview-tabs" aria-label="预览视图">${['source','prompt'].map(view=>cumulativeButton(view==='source'?'上下文预览':'提示词预览',`preview-${view}`,false,'tertiary',`aria-pressed="${state.previewView===view}"`)).join('')}</nav>${body}</section>`;
}
export function cumulativeGenerationMarkup(state,stopIntent=false){const p=state.params??{},auto=state.automatic,review=state.route==='review',busy=state.busy||state.unconfirmed||state.reloadInvalidated||state.task?.outcome==='unconfirmed',running=['starting','running','committing'].includes(state.task?.status),canStop=state.origin==='auto'&&(['running','waiting'].includes(auto.status)||auto.status==='awaiting-user'&&state.taskId===auto.taskId),number=(key,label)=>`<label class="ui-field"><span class="ui-field__label">${label}</span><input class="ui-input" type="number" min="${key==='batchSize'?1:0}" step="1" inputmode="numeric" ${busy||running||canStop||state.task?.status==='awaiting-user'?'disabled':''} data-cu-field="param:${key}" value="${esc(p[key]??(key==='endFloor'?state.latestFloor:''))}"></label>`;
  const frozen=busy||running||state.task?.status==='awaiting-user'||canStop;
  const choices=[['includeUser','包含用户消息'],['checkBeforeSave','入库前检查'],['hideSource','成功入库后隐藏来源楼层']].map(([key,label])=>`<label class="ui-choice ui-choice--control-only ui-hit-owner"><input class="ui-input" type="checkbox" data-cu-field="param:${key}" ${p[key]?'checked':''} ${frozen?'disabled':''}><span>${label}</span><span class="ui-hit-area" aria-hidden="true"></span></label>`).join('');
  const history=`<details class="lt-summary-history ui-disclosure" data-cu-open="generation-history"><summary>总结记录与重新生成</summary>${(state.cumulative?.versions??[]).map(version=>`<div class="lt-summary-history-row ui-disclosure-body"><span>${esc(cumulativeRange(version))} 楼</span>${version.id===state.cumulative.currentVersionId?cumulativeButton('重新生成',`regenerate:${version.id}`,busy||running):''}</div>`).join('')||'<p class="lt-meta ui-disclosure-body">暂无总结记录</p>'}</details>`;
  const parameters=state.origin==='auto'?`<div class="lt-summary-range ui-field-grid">${number('startFloor','开始楼')}${number('batchSize','每隔多少楼总结')}</div>`:`<div class="lt-summary-range ui-field-grid">${number('startFloor','开始楼')}${number('endFloor','结束楼')}</div>`;
  const body=review?`<section class="lt-summary-candidate lt-editor">${state.draft?cumulativeFields(state.draft):''}<p class="lt-meta">来源楼层 ${esc(cumulativeRange(state.task?.candidate?.version))}</p></section>`:`<section class="lt-summary-section ui-section"><h2>${state.origin==='auto'?'总结范围':'楼层范围'}</h2>${parameters}</section><section class="lt-summary-section ui-section"><h2>生成选项</h2><div class="lt-summary-choices ui-choice-group" data-ui-interaction-profile="compact-group-candidate">${choices}</div></section>${history}<div class="lt-summary-connection" data-preview-open="${state.previewOpen}"><div class="lt-summary-access ui-status-grid"><div class="ui-status-cell" data-selected="${state.previewOpen}"><span>发送内容</span>${cumulativeButton(state.previewOpen?'收起':'预览','preview',busy)}</div><div class="ui-status-cell"><span>总结进度</span><span class="ui-progress-text">第${state.cumulative?.progress.lastProcessedFloor??'—'}楼</span></div><div class="ui-status-cell"><span>总结设置</span>${cumulativeButton('打开','settings',busy)}</div></div>${preview(state)}</div>`;
  let footer;if(stopIntent&&canStop&&!auto.stopRequested)footer=`<div class="lt-editor-actions">${cumulativeButton('取消','cancel-stop')}${cumulativeButton('确认停止','confirm-stop',false,'secondary')}</div>`;
  else {const stop=canStop?cumulativeButton(auto.stopRequested?'已请求停止，等待本批完成':'本批次完成后停止总结','stop',auto.stopRequested):'';footer=review?`${stop}${cumulativeButton('采用总结','confirm',busy,'primary')}`:canStop?stop:cumulativeButton(running?'正在生成…':state.origin==='auto'&&auto.status!=='idle'?'继续总结':'开始总结','start',busy||running,'primary');}
  return `<section class="lantai lt-summary-workspace ui-workspace ui-graphic-controls" data-ui-theme="memphis"><header class="lt-header ui-header ui-header--centered">${cumulativeIcon('back',review?'放弃本批审核':'返回古法记忆','back')}<h1 class="ui-page-title">${review?'检查总结结果':state.origin==='auto'?'自动总结':'手动总结'}</h1>${cumulativeIcon('close','关闭兰台本末','close')}</header><main class="lt-main lt-summary-main ui-main ui-main--summary" tabindex="-1"><p class="lt-error" role="alert" ${state.error?'':'hidden'}>${esc(state.error)}</p>${body}${state.cumulative?.pending&&!state.taskId?cumulativeButton('放弃保留草稿','discard-pending',busy):''}${cumulativeButton('重新读取','read',state.busy,'tertiary',state.unconfirmed||state.reloadInvalidated||state.task?.outcome==='unconfirmed'?'':'hidden')}</main><p class="lt-saved lt-status" data-cu-toast role="status" hidden></p><footer class="lt-footer ui-action-footer">${footer}</footer></section>`;
}
export function mountCumulativeView({container,controller,onBack=()=>{},onClose=()=>{},openSettings=()=>{}}={}){let stopIntent=false; const footerOnly=focus=>{const template=document.createElement('template');template.innerHTML=cumulativeGenerationMarkup(controller.inspect(),stopIntent);const node=container.querySelector('.lt-footer');if(node)node.innerHTML=template.content.querySelector('.lt-footer').innerHTML;container.querySelector(`[data-cu-action="${focus}"]`)?.focus({preventScroll:true});};
  const view=mountCumulativeSurface({container,controller,markup:state=>cumulativeGenerationMarkup(state,stopIntent),input(node){const [kind,key]=(node.dataset.cuField??'').split(':');if(kind==='param')controller.changeParams(p=>p[key]=node.type==='checkbox'?node.checked:node.value===''?(key==='endFloor'?null:NaN):Number(node.value));if(kind==='draft')controller.changeDraft(d=>d[key]=node.value);},async click(action,node,event,render){if(action==='stop'){stopIntent=true;footerOnly('cancel-stop');return;}if(action==='cancel-stop'){stopIntent=false;footerOnly('stop');return;}if(action==='confirm-stop'){stopIntent=false;controller.stop();render();return;}if(action==='back'){if(await controller.back())onBack();return;}if(action==='close'){stopIntent=false;onClose();return;}if(action==='settings'){openSettings();return;}if(action==='preview'){if(controller.inspect().preview)controller.togglePreview();else await controller.preview();return;}if(action.startsWith('preview-')){controller.previewView(action.slice(8));return;}if(action.startsWith('regenerate:')){await controller.regenerate(action.slice(11));return;}if(['start','confirm','retry','read'].includes(action))await controller[action]();if(action==='discard-pending')await controller.discardPending();}});return {dispose(){view.dispose();}};
}
